package roleproof

import (
 "time"
 h "foundry.test/goway/models/hooks"
 "github.com/weiloon1234/Foundry-Go/database/orm"
 "github.com/weiloon1234/Foundry-Go/database/orm/expr"
 "github.com/weiloon1234/Foundry-Go/database/orm/rows"
 "github.com/weiloon1234/Foundry-Go/value"
)

type Row struct{ ID int64; Text string; At time.Time; Deleted value.Nullable[time.Time] }

// The purported managed-time roles are exactly the ordinary time types.
var _ orm.Time[Row,time.Time] = orm.UpdatedAt[Row,time.Time]{}
var _ orm.Time[Row,time.Time] = orm.CreatedAt[Row,time.Time]{}
var _ orm.NullableTime[Row,time.Time] = orm.SoftDelete[Row,time.Time]{}
var _ func(orm.Builder[Row],*time.Time) orm.Time[Row,time.Time] = orm.UpdatedAtOf[Row,time.Time]
var _ func(orm.Builder[Row],*value.Nullable[time.Time]) orm.NullableTime[Row,time.Time] = orm.SoftDeleteOf[Row,time.Time]

// KeyColumn is a shared comparable-column interface, not a primary-role type.
var _ orm.KeyColumn[Row,int64] = orm.Column[Row,int64]{}
var _ orm.KeyColumn[Row,int64] = orm.Number[Row,int64]{}
var _ func(orm.Key[Row,int64]) orm.Number[Row,int64] = orm.NumberKey[Row,int64]

// This real fixture's Name has MutateName but is ordinary Text.
var _ orm.Text[h.Member,string] = h.Members.Name
var _ orm.InsertMapping[h.Member,h.Member] = rows.MapInsert(h.Members.Name,expr.Value(h.Members.Name))
var _ orm.UpdateMapping[h.Member,h.Member] = rows.MapUpdate(h.Members.Name,expr.Value(h.Members.Name))

// Source writes likewise see identical types for conventional update timestamps.
var _ orm.Time[h.Member,time.Time] = h.Members.UpdatedAt
var _ orm.InsertMapping[h.Member,h.Member] = rows.MapInsert(h.Members.UpdatedAt,expr.Value(h.Members.UpdatedAt))

