// Measurement-only lower bound: methodless phantom roles, not an API proposal.
// These carry no validated declaration semantics and are deliberately unexported.
type ordinaryRole struct{}
type primaryRole struct{}
type mutatedRole struct{}
type updatedRole struct{}
type softRole struct{}
type roleCarrier[M,V,R any] struct { _ [0]*M; _ [0]*V; _ [0]*R; owner *byte }
var NameRole roleCarrier[m.WriteRecord,string,ordinaryRole]
var KeyRole roleCarrier[m.WriteRecord,m.RecordKey,primaryRole]
var InputRole roleCarrier[m.WriteRecord,string,mutatedRole]
var TimestampRole roleCarrier[m.WriteRecord,int64,updatedRole]
var DeletionRole roleCarrier[m.WriteRecord,int64,softRole]
